pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testRegression_property() public {
        vm.deal(address(c), 1 ether);

        address[] memory emptyTos = new address[](0);
        bool ok;
        try c.transfer(address(0), address(0), emptyTos, 0) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "Reference reverts, mutant should pass");
    }
}
